## Why This Is Asked
This question evaluates advanced JavaScript patterns including per-key caching, Promise deduplication, TTL-based eviction, and reactive update patterns commonly needed in frontend applications.

## Key Concepts
- **Closures and per-key maps**: Isolated state management for each cached key
- **Promise deduplication**: Avoiding redundant network requests for concurrent loads of the same key
- **TTL-based eviction**: Time-to-live expiration for cache entries
- **Change notifications**: Listener pattern for broadcasting data updates
- **Error handling**: Graceful handling of fetch failures and cache misses

## Code Example
```javascript
function createDataLoader(fetchFn, ttlMs) {
  const cache = new Map();

  function getEntry(key) {
    if (!cache.has(key)) {
      cache.set(key, { promise: null, data: null, expiry: 0, listeners: [] });
    }
    return cache.get(key);
  }

  const notify = (key, data, error) => {
    const entry = cache.get(key);
    if (entry?.listeners.length) {
      entry.listeners.forEach(cb => cb(data, error));
    }
  };

  return {
    load(key) {
      const entry = getEntry(key);
      const now = Date.now();

      if (entry.data && entry.expiry > now) {
        return Promise.resolve(entry.data);
      }

      if (entry.promise) {
        return entry.promise;
      }

      entry.promise = fetchFn(key)
        .then(data => {
          entry.data = data;
          entry.expiry = now + ttlMs;
          entry.promise = null;
          notify(key, data, null);
          return data;
        })
        .catch(err => {
          entry.promise = null;
          notify(key, null, err);
          throw err;
        });

      return entry.promise;
    },

    invalidate(key) {
      const entry = cache.get(key);
      if (entry) {
        entry.data = null;
        entry.expiry = 0;
        entry.promise = null;
      }
    },

    onChange(key, cb) {
      const entry = getEntry(key);
      entry.listeners.push(cb);
      return () => {
        entry.listeners = entry.listeners.filter(l => l !== cb);
      };
    }
  };
}
```

## Usage Example
```javascript
const loader = createDataLoader(fetchUser, 5000);

// Two different keys
loader.onChange('user:1', (data) => console.log('User 1 updated:', data));
loader.onChange('user:2', (data) => console.log('User 2 updated:', data));

// Concurrent loads for same key are deduplicated
loader.load('user:1').then(console.log);
loader.load('user:1').then(console.log); // Reuses in-flight request

// Invalidate and reload
loader.invalidate('user:1');
loader.load('user:1');
```

## Eviction Strategies
- **TTL-based**: Automatic expiration after ttlMs (implemented above)
- **LRU**: Evict least recently used entries when cache size exceeds limit
- **Manual**: Explicit invalidate() calls

## Error Handling
- Failed fetches propagate errors to all waiters via rejected Promise
- Listeners receive error state for reactive UI updates
- In-flight promises are cleared on error to allow retries

## Why This Is Asked
This question tests your ability to design per-tenant, real-time UI systems with correct subscription lifecycles andization.

## Key Concepts
 performance optimization through memo- useSyncExternalStore with per-tenant data streams
- memoized selectors with stable identity keys
- React.memo for row component optimization
- conditional rendering with FeatureGate wrapper
- proper cleanup on tenant switch

## Code Example
```javascript
// Store wrapper - creates per-tenant subscription
function createTenantFlagStore(tenantId) {
  let flags = {};
  const subscribers = new Set();

  return {
    getSnapshot: () => flags,
    getServerSnapshot: () => ({}),
    subscribe: (callback) => {
      subscribers.add(callback);
      return () => subscribers.delete(callback);
    },
    updateFlag: (featureName, value) => {
      flags = { ...flags, [featureName]: value };
      subscribers.forEach(cb => cb(flags));
    }
  };
}

// Memoized selector keyed by tenantId and featureName
const featureSelectorCache = new Map();
function selectFeature(tenantId, featureName, tenantStore) {
  const key = `${tenantId}:${featureName}`;
  if (!featureSelectorCache.has(key)) {
    featureSelectorCache.set(key, createSelector(tenantStore, flags => ({
      enabled: flags[featureName]?.enabled ?? false,
      loading: flags[featureName]?.loading ?? true,
      visible: flags[featureName]?.visible ?? true
    })));
  }
  return featureSelectorCache.get(key)(useSyncExternalStore(
    tenantStore.subscribe,
    tenantStore.getSnapshot,
    tenantStore.getServerSnapshot
  ));
}

// Memoized FeatureRow
const FeatureRow = React.memo(function FeatureRow({ featureName, tenantId, store }) {
  const feature = selectFeature(tenantId, featureName, store);
  return (
    <div className="feature-row">
      {feature.loading ? <Spinner /> : 
       feature.enabled ? <FeatureContent name={featureName} /> : 
       <FeatureDisabled />}
    </div>
  );
}, (prevProps, nextProps) => {
  return prevProps.tenantId === nextProps.tenantId && 
         prevProps.featureName === nextProps.featureName;
});

// FeatureGate wrapper
function FeatureGate({ tenantId, featureName, children, fallback = null }) {
  const store = useTenantStore(tenantId);
  const feature = selectFeature(tenantId, featureName, store);

  return feature.enabled ? children : fallback;
}

// Panel integration with cleanup
function FeatureDashboard({ tenantId }) {
  const [currentTenant, setCurrentTenant] = useState(tenantId);

  useEffect(() => {
    if (currentTenant !== tenantId) {
      setCurrentTenant(tenantId);
    }
  }, [tenantId]);

  return (
    <FeatureGate tenantId={tenantId} featureName="dashboard_v2">
      <FeatureRow 
        tenantId={tenantId} 
        featureName="realtime_metrics"
        store={useTenantStore(tenantId)}
      />
    </FeatureGate>
  );
}
```

## Key Takeaways
The solution demonstrates proper separation of concerns: the store handles subscription management, selectors compute derived state efficiently, and components use React.memo to avoid unnecessary re-renders. The FeatureGate provides declarative access control, and cleanup on tenant switch is handled by useEffect's cleanup function in the store subscription.

## Why This Is Asked
Tests ability to integrate per-tenant manifests with React concurrent rendering patterns, while ensuring minimal re-renders and clean switch semantics.

## Key Concepts
- useSyncExternalStore for per-tenant streams
- memoization via Map keyed by (tenantId, widgetId)
- React.lazy + Suspense for dynamic widgets
- React.memo to prevent unnecessary renders

## Code Example
```javascript
// sketch: memoized prop selector
const propCache = new Map();
function getWidgetProps(tenantId, widgetId, manifest, globalProps){
  const key = `${tenantId}::${widgetId}`;
  if (propCache.has(key)) return propCache.get(key);
  const w = manifest.widgets.find(w => w.id===widgetId);
  const props = { ...globalProps, ...w?.props };
  propCache.set(key, props);
  return props;
}
```

